:root {
  /* Surface / Elevation */
  --color-bg: #f6f5f1;
  --color-surface: #ffffff;
  --color-surface-raised: #f0eee8;
  --color-surface-overlay: #ffffff;
  --color-surface-sunken: #eae7e0;
  --color-surface-inverse: #1a1917;

  /* Text */
  --color-text: #1a1917;
  --color-text-secondary: #48453e;
  --color-text-muted: #716e65;
  --color-text-disabled: #a09d94;
  --color-text-link: #2b5042;
  --color-text-inverse: #f6f5f1;
  --color-text-link-hover: #b8421e;
  --color-text-on-accent: #ffffff;

  /* Border / Divider */
  --color-border: #1a1917;
  --color-border-subtle: #dcd8ce;
  --color-border-strong: #1a1917;
  --color-divider: #e4e0d5;

  /* Accent / Brand */
  --color-accent: #b8421e;
  --color-accent-hover: #963314;
  --color-accent-active: #78260e;
  --color-accent-subtle: #fbf0ec;
  --color-accent-muted: #e5a490;
  --color-accent-border: #b8421e;
  --color-accent-text: #963314;
  --color-on-accent: #ffffff;
  --color-accent-secondary: #2b5042;
  --color-accent-secondary-subtle: #edf3f0;

  /* Disabled / Inert */
  --color-surface-disabled: #edebe4;
  --color-border-disabled: #d0ccbf;
  --color-icon-disabled: #a09d94;

  /* Form / Input */
  --color-input-bg: #ffffff;
  --color-input-border: #1a1917;
  --color-input-border-focus: #b8421e;
  --color-input-placeholder: #716e65;
  --color-input-bg-hover: #fbf9f5;
  --color-input-bg-disabled: #edebe4;
  --color-input-border-hover: #48453e;
  --color-input-border-error: #c82828;
  --color-input-text: #1a1917;
  --color-input-icon: #48453e;

  /* Brand Scale (primitive) */
  --color-brand-50: #fbf0ec;
  --color-brand-100: #f6dbd1;
  --color-brand-200: #ecb29f;
  --color-brand-300: #e2896d;
  --color-brand-400: #d4603d;
  --color-brand-500: #b8421e;
  --color-brand-600: #963314;
  --color-brand-700: #78260e;
  --color-brand-800: #5a1a08;
  --color-brand-900: #3d0e03;

  /* Neutral Scale */
  --color-neutral-50: #fdfdfc;
  --color-neutral-100: #f6f5f1;
  --color-neutral-200: #f0eee8;
  --color-neutral-300: #eae7e0;
  --color-neutral-400: #dcd8ce;
  --color-neutral-500: #a09d94;
  --color-neutral-600: #716e65;
  --color-neutral-700: #48453e;
  --color-neutral-800: #2a2825;
  --color-neutral-900: #1a1917;
  --color-neutral-950: #11100f;
  --color-neutral-1000: #000000;

  /* Data Visualization */
  --color-chart-1: #b8421e;
  --color-chart-2: #2b5042;
  --color-chart-3: #d07d2c;
  --color-chart-4: #4a6fa5;
  --color-chart-5: #8c5383;
  --color-chart-6: #588157;
  --color-chart-7: #a3485e;
  --color-chart-8: #3d5a80;
  --color-chart-grid: #dcd8ce;
  --color-chart-axis: #1a1917;
  --color-chart-tooltip-bg: #1a1917;

  /* Interaction */
  --color-focus-ring: #b8421e;
  --color-hover-overlay: rgba(26, 25, 23, 0.04);
  --color-active-overlay: rgba(26, 25, 23, 0.08);
  --color-selected: #f0eee8;
  --color-selected-subtle: #fbf0ec;
  --color-pressed-overlay: rgba(26, 25, 23, 0.12);

  /* Semantic State */
  --color-success: #1e6b3c;
  --color-success-subtle: #eaf5ee;
  --color-success-muted: #8ec39e;
  --color-success-border: #1e6b3c;
  --color-success-text: #144928;
  --color-on-success: #ffffff;
  --color-warning: #9e6100;
  --color-warning-subtle: #fef7e6;
  --color-warning-muted: #f3c26d;
  --color-warning-border: #9e6100;
  --color-warning-text: #6b4100;
  --color-on-warning: #ffffff;
  --color-danger: #c82828;
  --color-danger-subtle: #fdf0f0;
  --color-danger-muted: #f09b9b;
  --color-danger-border: #c82828;
  --color-danger-text: #961919;
  --color-on-danger: #ffffff;
  --color-info: #1b5e83;
  --color-info-subtle: #ebf4f9;
  --color-info-muted: #8dbedc;
  --color-info-border: #1b5e83;
  --color-info-text: #113f59;
  --color-on-info: #ffffff;

  /* Alpha / Overlay */
  --color-scrim: rgba(26, 25, 23, 0.6);
  --color-shadow: rgba(26, 25, 23, 0.08);
  --color-tint-subtle: rgba(184, 66, 30, 0.05);

  /* Font Family */
  --font-sans: "IBM Plex Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-serif: "Instrument Serif", "Georgia", "Times New Roman", serif;
  --font-mono: "IBM Plex Mono", "Courier New", monospace;
  --font-display: "Instrument Serif", "Georgia", serif;

  /* Display Size */
  --font-size-display-xs: clamp(2rem, 3.5vw, 2.5rem);
  --font-size-display-sm: clamp(2.5rem, 4.5vw, 3.25rem);
  --font-size-display-md: clamp(3.25rem, 6vw, 4.25rem);
  --font-size-display-lg: clamp(4.25rem, 8vw, 5.75rem);
  --font-size-display-xl: clamp(5.5rem, 11vw, 7.5rem);

  /* Font Size */
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;
  --font-size-7xl: 4.5rem;

  /* Font Weight */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Line Height */
  --line-height-tight: 1.1;
  --line-height-snug: 1.25;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.65;
  --line-height-none: 1;
  --line-height-loose: 1.8;

  /* Letter Spacing */
  --letter-spacing-tight: -0.02em;
  --letter-spacing-normal: 0em;
  --letter-spacing-wide: 0.04em;
  --letter-spacing-wider: 0.08em;
  --letter-spacing-tighter: -0.04em;

  /* Text Measure */
  --text-measure-xs: 32ch;
  --text-measure-sm: 45ch;
  --text-measure-md: 60ch;
  --text-measure-lg: 72ch;
  --text-measure-xl: 84ch;
  --text-measure-wide: 100ch;

  /* Spacing */
  --space-0: 0px;
  --space-px: 1px;
  --space-0-5: 0.125rem;
  --space-1: 0.25rem;
  --space-1-5: 0.375rem;
  --space-2: 0.5rem;
  --space-2-5: 0.625rem;
  --space-3: 0.75rem;
  --space-3-5: 0.875rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-7: 1.75rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-14: 3.5rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-28: 7rem;
  --space-32: 8rem;
  --space-40: 10rem;
  --space-48: 12rem;
  --space-56: 14rem;
  --space-64: 16rem;
  --space-72: 18rem;
  --space-80: 20rem;
  --space-96: 24rem;

  /* Section Spacing */
  --section-space-xs: 2rem;
  --section-space-sm: 3.5rem;
  --section-space-md: 5rem;
  --section-space-lg: 7rem;
  --section-space-xl: 9rem;
  --section-space-2xl: 12rem;
  --section-space-3xl: 16rem;

  /* Border Radius */
  --radius-none: 0px;
  --radius-xs: 1px;
  --radius-sm: 2px;
  --radius-md: 3px;
  --radius-lg: 4px;
  --radius-xl: 6px;
  --radius-2xl: 8px;
  --radius-3xl: 12px;
  --radius-full: 9999px;

  /* Border Width */
  --border-width-none: 0px;
  --border-width-thin: 1px;
  --border-width-medium: 2px;
  --border-width-thick: 4px;

  /* Layout / Grid */
  --container-max-width-xs: 480px;
  --container-max-width-sm: 640px;
  --container-max-width-md: 768px;
  --container-max-width-lg: 1024px;
  --container-max-width-xl: 1280px;
  --container-max-width-2xl: 1536px;
  --container-padding-sm: 1rem;
  --container-padding-md: 1.5rem;
  --container-padding-lg: 2.5rem;
  --container-padding-xl: 3.5rem;
  --container-padding-2xl: 4.5rem;
  --grid-columns: 12;
  --grid-columns-sm: 4;
  --grid-columns-md: 8;
  --grid-columns-lg: 12;
  --grid-columns-xl: 12;
  --grid-gutter: 1.5rem;
  --grid-gutter-sm: 1rem;
  --grid-gutter-md: 1.25rem;
  --grid-gutter-lg: 1.75rem;
  --grid-gutter-xl: 2.25rem;
  --grid-margin-sm: 1rem;
  --grid-margin-md: 1.5rem;
  --grid-margin-lg: 2.5rem;
  --grid-margin-xl: 3.5rem;

  /* Composition */
  --composition-max-width: 1360px;
  --composition-max-width-wide: 1600px;
  --composition-max-width-narrow: 960px;
  --composition-gutter: 2rem;
  --composition-offset-sm: 1.5rem;
  --composition-offset-md: 3rem;
  --composition-offset-lg: 4.5rem;
  --composition-overlap-sm: -1.5rem;
  --composition-overlap-md: -3rem;
  --composition-overlap-lg: -4.5rem;
  --composition-aspect-wide: 21 / 9;
  --composition-aspect-standard: 16 / 9;
  --composition-aspect-square: 1 / 1;
  --composition-aspect-portrait: 3 / 4;

  /* Media */
  --media-radius: 0px;
  --media-radius-sm: 0px;
  --media-radius-lg: 2px;
  --media-radius-xl: 4px;
  --media-aspect-wide: 21 / 9;
  --media-aspect-video: 16 / 9;
  --media-aspect-standard: 4 / 3;
  --media-aspect-square: 1 / 1;
  --media-aspect-portrait: 3 / 4;
  --media-overlay: rgba(26, 25, 23, 0.4);
  --media-overlay-subtle: rgba(26, 25, 23, 0.15);
  --media-overlay-strong: rgba(26, 25, 23, 0.75);

  /* Sizes */
  --size-icon-xs: 0.875rem;
  --size-icon-sm: 1rem;
  --size-icon-md: 1.25rem;
  --size-icon-lg: 1.5rem;
  --size-icon-xl: 2rem;
  --size-control-xs: 1.75rem;
  --size-control-sm: 2.25rem;
  --size-control-md: 2.75rem;
  --size-control-lg: 3.25rem;
  --size-control-xl: 3.75rem;
  --size-avatar-xs: 1.5rem;
  --size-avatar-sm: 2rem;
  --size-avatar-md: 2.75rem;
  --size-avatar-lg: 3.5rem;
  --size-avatar-xl: 4.5rem;
  --size-header-height: 4rem;
  --size-header-height-mobile: 3.5rem;
  --size-sidebar-width: 18rem;
  --size-sidebar-width-collapsed: 4rem;

  /* Control Geometry */
  --control-padding-x-xs: 0.5rem;
  --control-padding-x-sm: 0.75rem;
  --control-padding-x-md: 1.25rem;
  --control-padding-x-lg: 1.75rem;
  --control-padding-x-xl: 2.25rem;
  --control-padding-y-xs: 0.25rem;
  --control-padding-y-sm: 0.375rem;
  --control-padding-y-md: 0.625rem;
  --control-padding-y-lg: 0.875rem;
  --control-padding-y-xl: 1.125rem;
  --control-radius: 1px;
  --control-border-width: 1px;
  --control-icon-gap: 0.5rem;

  /* Iconography */
  --icon-stroke-width-thin: 1px;
  --icon-stroke-width: 1.5px;
  --icon-stroke-width-medium: 2px;
  --icon-stroke-width-bold: 2.5px;
  --icon-gap-xs: 0.25rem;
  --icon-gap-sm: 0.375rem;
  --icon-gap-md: 0.5rem;

  /* Shadow / Elevation */
  --shadow-xs: 0 1px 2px rgba(26, 25, 23, 0.05);
  --shadow-sm: 0 2px 4px rgba(26, 25, 23, 0.06);
  --shadow-md: 0 4px 12px rgba(26, 25, 23, 0.08);
  --shadow-lg: 0 8px 24px rgba(26, 25, 23, 0.1);
  --shadow-xl: 0 16px 40px rgba(26, 25, 23, 0.12);
  --shadow-2xl: 0 24px 60px rgba(26, 25, 23, 0.16);
  --shadow-inner: inset 0 2px 4px rgba(26, 25, 23, 0.06);
  --shadow-focus: 0 0 0 2px #f6f5f1, 0 0 0 4px #b8421e;
  --shadow-outline: 0 0 0 1px #1a1917;

  /* Glow / Light Effects */
  --glow-sm: 0 0 8px rgba(184, 66, 30, 0.2);
  --glow-md: 0 0 16px rgba(184, 66, 30, 0.25);
  --glow-lg: 0 0 24px rgba(184, 66, 30, 0.3);
  --glow-xl: 0 0 36px rgba(184, 66, 30, 0.35);

  /* Blur */
  --blur-sm: 4px;
  --blur-md: 8px;
  --blur-lg: 16px;
  --blur-xl: 24px;

  /* Gradient */
  --gradient-brand: linear-gradient(135deg, #b8421e 0%, #78260e 100%);
  --gradient-brand-subtle: linear-gradient(180deg, #fbf0ec 0%, #f6f5f1 100%);
  --gradient-surface: linear-gradient(180deg, #ffffff 0%, #f6f5f1 100%);
  --gradient-surface-subtle: linear-gradient(180deg, #f0eee8 0%, #eae7e0 100%);
  --gradient-glow: radial-gradient(circle at center, rgba(184, 66, 30, 0.15) 0%, transparent 70%);
  --gradient-fade: linear-gradient(180deg, rgba(246, 245, 241, 0) 0%, #f6f5f1 100%);
  --gradient-hero: linear-gradient(90deg, #1a1917 0%, #2a2825 100%);

  /* Opacity */
  --opacity-hover: 0.92;
  --opacity-disabled: 0.45;
  --opacity-active: 0.85;
  --opacity-selected: 1;
  --opacity-muted: 0.65;
  --opacity-overlay: 0.6;

  /* Duration */
  --duration-instant: 0ms;
  --duration-fast: 120ms;
  --duration-normal: 200ms;
  --duration-slow: 350ms;
  --duration-slower: 500ms;
  --duration-slowest: 800ms;

  /* Motion Distance */
  --motion-distance-xs: 2px;
  --motion-distance-sm: 4px;
  --motion-distance-md: 8px;
  --motion-distance-lg: 16px;
  --motion-distance-xl: 32px;

  /* Motion Scale */
  --motion-scale-hover: 1.01;
  --motion-scale-active: 0.99;
  --motion-scale-enter: 0.97;
  --motion-scale-exit: 0.98;

  /* Motion Blur */
  --motion-blur-enter: 4px;
  --motion-blur-exit: 2px;

  /* Easing */
  --ease-linear: cubic-bezier(0, 0, 1, 1);
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.1);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-emphasized: cubic-bezier(0.2, 0, 0, 1);

  /* Semantic Motion */
  --motion-enter: transform 200ms cubic-bezier(0, 0, 0.2, 1), opacity 200ms cubic-bezier(0, 0, 0.2, 1);
  --motion-exit: transform 120ms cubic-bezier(0.4, 0, 1, 1), opacity 120ms cubic-bezier(0.4, 0, 1, 1);
  --motion-hover: background-color 120ms cubic-bezier(0, 0, 0.2, 1), border-color 120ms cubic-bezier(0, 0, 0.2, 1);
  --motion-press: transform 80ms cubic-bezier(0, 0, 0.2, 1);
  --motion-reveal: transform 350ms cubic-bezier(0.16, 1, 0.3, 1), opacity 350ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-layout: all 200ms cubic-bezier(0.2, 0, 0, 1);
  --motion-modal: transform 200ms cubic-bezier(0.16, 1, 0.3, 1), opacity 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-page: opacity 200ms cubic-bezier(0, 0, 0.2, 1);

  /* Z-Index */
  --z-base: 0;
  --z-raised: 10;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-overlay: 300;
  --z-modal: 400;
  --z-popover: 500;
  --z-toast: 600;
  --z-tooltip: 700;

  /* Breakpoint */
  --breakpoint-xs: 320px;
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  /* Accessibility */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --focus-ring-radius: 1px;
  --touch-target-min: 44px;

  /* Component / Button */
  --button-height-sm: 2rem;
  --button-height-md: 2.75rem;
  --button-height-lg: 3.25rem;
  --button-height-xl: 3.75rem;
  --button-padding-x-sm: 0.875rem;
  --button-padding-x-md: 1.25rem;
  --button-padding-x-lg: 1.75rem;
  --button-padding-x-xl: 2.25rem;
  --button-radius: 1px;
  --button-icon-size: 1.25rem;
  --button-gap: 0.5rem;

  /* Component / Card */
  --card-padding-sm: 1rem;
  --card-padding-md: 1.5rem;
  --card-padding-lg: 2.25rem;
  --card-padding-xl: 3rem;
  --card-radius: 2px;
  --card-border-width: 1px;
  --card-shadow: none;

  /* Component / Navigation */
  --nav-height: 4rem;
  --nav-padding-x: 1.5rem;
  --nav-gap: 2rem;
  --nav-item-height: 2.5rem;
  --nav-item-radius: 1px;

  /* Component / Badge */
  --badge-height-sm: 1.25rem;
  --badge-height-md: 1.625rem;
  --badge-padding-x: 0.5rem;
  --badge-radius: 1px;
  --badge-gap: 0.25rem;

  /* Component / Modal */
  --modal-width-sm: 400px;
  --modal-width-md: 560px;
  --modal-width-lg: 720px;
  --modal-width-xl: 960px;
  --modal-padding: 2rem;
  --modal-radius: 2px;
  --modal-shadow: 0 16px 40px rgba(26, 25, 23, 0.12);

  /* Component / Tooltip */
  --tooltip-max-width: 240px;
  --tooltip-padding-x: 0.625rem;
  --tooltip-padding-y: 0.375rem;
  --tooltip-radius: 1px;

  /* Component / Input */
  --input-height-sm: 2.25rem;
  --input-height-md: 2.75rem;
  --input-height-lg: 3.25rem;
  --input-padding-x: 0.875rem;
  --input-padding-y: 0.625rem;
  --input-radius: 1px;
  --input-border-width: 1px;

  /* Component / Avatar */
  --avatar-ring-width: 2px;
  --avatar-ring-color: #ffffff;
  --avatar-group-overlap: -0.5rem;

  /* Component / Divider */
  --divider-width: 1px;
  --divider-spacing: 1.5rem;

  /* Component / Overlay */
  --overlay-opacity: 0.6;
  --overlay-blur: 0px;
  --overlay-radius: 0px;

  /* Responsive Layout */
  --mobile-page-padding: 1rem;
  --mobile-section-spacing: 3rem;
  --mobile-content-gap: 1.25rem;
  --mobile-grid-gap: 1rem;
  --desktop-page-padding: 3.5rem;
  --desktop-section-spacing: 6rem;
  --desktop-content-gap: 2.5rem;
  --desktop-grid-gap: 2rem;
}
